package com.questpath.planner;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

import com.questpath.data.OverrideLoader;
import com.questpath.data.QuestRepository;
import com.questpath.data.WikiDataFetcher;
import com.questpath.game.PlayerState;
import com.questpath.game.QuestStatus;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Skill;
import org.junit.Before;
import org.junit.Test;

/**
 * End-to-end planner test against the real seed overrides.json. We don't mock
 * the repository — that defeats the point. Instead we verify the planner
 * produces a sensible plan against fully-known data.
 */
public class PathPlannerTest
{
	private static final String LUNAR_DIPLOMACY = "lunar_diplomacy";

	private PathPlanner planner;

	@Before
	public void setUp()
	{
		com.google.gson.Gson gson = new com.google.gson.Gson();
		QuestRepository repo = new QuestRepository(new OverrideLoader(gson), new WikiDataFetcher(gson));
		// null config — GapResolver falls back to weight=5 for each preference.
		GapResolver resolver = new GapResolver(repo, null);
		this.planner = new PathPlanner(repo, resolver);
	}

	@Test
	public void freshAccountTargetingLunarDiplomacyHasAllPrereqs()
	{
		Plan plan = planner.plan(LUNAR_DIPLOMACY, PlayerState.empty());

		assertEquals("lunar_diplomacy", plan.getTargetQuestId());
		assertFalse("Plan should not be empty for a fresh account", plan.getSteps().isEmpty());

		List<String> questIdsInOrder = questIdsFromPlan(plan);

		// All 7 seed quests should appear.
		String[] expected = {
			"druidic_ritual", "jungle_potion", "shilo_village",
			"rune_mysteries", "lost_city", "the_fremennik_trials", "lunar_diplomacy"
		};
		for (String q : expected)
		{
			assertTrue("Plan missing quest: " + q, questIdsInOrder.contains(q));
		}
		assertEquals(expected.length, plan.getQuestStepCount());
	}

	@Test
	public void planRespectsTopologicalOrder()
	{
		Plan plan = planner.plan(LUNAR_DIPLOMACY, PlayerState.empty());
		List<String> order = questIdsFromPlan(plan);
		Map<String, Integer> idx = new HashMap<>();
		for (int i = 0; i < order.size(); i++)
		{
			idx.put(order.get(i), i);
		}
		// Each chain edge must hold: prereq before dependent.
		assertBefore(idx, "druidic_ritual", "jungle_potion");
		assertBefore(idx, "jungle_potion", "shilo_village");
		assertBefore(idx, "shilo_village", "lunar_diplomacy");
		assertBefore(idx, "the_fremennik_trials", "lunar_diplomacy");
		assertBefore(idx, "lost_city", "lunar_diplomacy");
		assertBefore(idx, "rune_mysteries", "lunar_diplomacy");
	}

	@Test
	public void planEmitsTrainingOrSkillGateForUnmetSkillReqs()
	{
		Plan plan = planner.plan(LUNAR_DIPLOMACY, PlayerState.empty());

		// Lunar Diplomacy needs Magic 65 / Crafting 61 / Firemaking 49 etc.
		// At level-1 across the board, every gate must surface as TRAINING or SKILL_GATE.
		int trainingOrGate = plan.getTrainingStepCount() + plan.getSkillGateStepCount();
		assertTrue("Expected at least one training/gate step on a fresh account, got "
			+ trainingOrGate, trainingOrGate > 0);
	}

	@Test
	public void allRequirementsMetProducesQuestsOnly()
	{
		// Player has every skill at 99 → no skill gates surface.
		PlayerState.PlayerStateBuilder builder = PlayerState.builder();
		for (Skill s : Skill.values())
		{
			if (s == Skill.OVERALL)
			{
				continue;
			}
			builder.skillLevel(s, 99);
		}
		Plan plan = planner.plan(LUNAR_DIPLOMACY, builder.build());

		assertEquals("No training when all skills 99", 0, plan.getTrainingStepCount());
		assertEquals("No skill gates when all skills 99", 0, plan.getSkillGateStepCount());
		assertTrue("Quests should still be present",
			plan.getQuestStepCount() > 0);
	}

	@Test
	public void targetAlreadyDoneProducesEmptyPlan()
	{
		PlayerState done = PlayerState.builder()
			.questState(LUNAR_DIPLOMACY, QuestStatus.DONE)
			.questState("druidic_ritual", QuestStatus.DONE)
			.questState("jungle_potion", QuestStatus.DONE)
			.questState("shilo_village", QuestStatus.DONE)
			.questState("rune_mysteries", QuestStatus.DONE)
			.questState("lost_city", QuestStatus.DONE)
			.questState("the_fremennik_trials", QuestStatus.DONE)
			.build();
		Plan plan = planner.plan(LUNAR_DIPLOMACY, done);
		assertTrue("Plan should be empty when target already done", plan.isAlreadyComplete());
	}

	@Test
	public void unknownTargetReturnsEmptyPlan()
	{
		Plan plan = planner.plan("not_a_real_quest", PlayerState.empty());
		assertNotNull(plan);
		assertTrue(plan.getSteps().isEmpty());
	}

	private static void assertBefore(Map<String, Integer> idx, String earlier, String later)
	{
		Integer a = idx.get(earlier);
		Integer b = idx.get(later);
		assertNotNull("Plan missing quest: " + earlier, a);
		assertNotNull("Plan missing quest: " + later, b);
		assertTrue(earlier + " should appear before " + later
			+ " (got " + a + " vs " + b + ")", a < b);
	}

	private static List<String> questIdsFromPlan(Plan plan)
	{
		List<String> ids = new ArrayList<>();
		for (PlanStep step : plan.getSteps())
		{
			if (step.getType() == PlanStepType.QUEST)
			{
				ids.add(step.getReferenceId());
			}
		}
		return ids;
	}
}

package com.questpath.data;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

import net.runelite.api.Skill;
import org.junit.Before;
import org.junit.Test;

/**
 * Sanity checks for the bundled overrides.json. Catches:
 *   - JSON shape regressions (rename a field and forget to update data)
 *   - Missing key quests in the seed Lunar Diplomacy chain
 *   - Skill enum name changes (Skill.WOODCUTTING → ...)
 *
 * Doesn't test data accuracy against the wiki — that's a Phase 6 problem.
 */
public class OverrideLoaderTest
{
	private OverrideData data;

	@Before
	public void setUp()
	{
		data = new OverrideLoader(new com.google.gson.Gson()).getData();
	}

	@Test
	public void overrideFileLoadsAndParses()
	{
		assertNotNull("OverrideData was null", data);
		assertNotNull("quests map was null", data.getQuests());
		assertNotNull("trainingMethods list was null", data.getTrainingMethods());

		assertFalse("Expected at least one quest in seed data", data.getQuests().isEmpty());
		assertFalse("Expected at least one training method in seed data",
			data.getTrainingMethods().isEmpty());
	}

	@Test
	public void lunarDiplomacyHasExpectedShape()
	{
		QuestDefinition lunar = data.getQuests().get("lunar_diplomacy");
		assertNotNull("Lunar Diplomacy missing from seed data", lunar);

		assertEquals("lunar_diplomacy", lunar.getId());
		assertEquals("Lunar Diplomacy", lunar.getDisplayName());
		assertTrue("Lunar Diplomacy should be members-only", lunar.isMembers());

		assertTrue("Lunar Diplomacy should require Fremennik Trials",
			lunar.getPrerequisiteQuestIds().contains("the_fremennik_trials"));
		assertTrue("Lunar Diplomacy should require Lost City",
			lunar.getPrerequisiteQuestIds().contains("lost_city"));
		assertTrue("Lunar Diplomacy should require Rune Mysteries",
			lunar.getPrerequisiteQuestIds().contains("rune_mysteries"));
		assertTrue("Lunar Diplomacy should require Shilo Village",
			lunar.getPrerequisiteQuestIds().contains("shilo_village"));

		Integer magicReq = lunar.getSkillRequirements().get(Skill.MAGIC);
		assertNotNull("Lunar Diplomacy should have a Magic requirement", magicReq);
		assertEquals("Lunar Diplomacy Magic req", 65, (int) magicReq);

		Integer craftingReq = lunar.getSkillRequirements().get(Skill.CRAFTING);
		assertNotNull("Lunar Diplomacy should have a Crafting requirement", craftingReq);
		assertEquals("Lunar Diplomacy Crafting req", 61, (int) craftingReq);
	}

	@Test
	public void chainedPrereqsAllResolve()
	{
		// Override entries are allowed to reference quests that live in the
		// bundled wiki snapshot rather than the overrides file (e.g. our
		// curse_of_the_empty_lord override references desert_treasure /
		// the_restless_ghost which come from the wiki bundle). So we
		// validate against the *merged* repository view, not just overrides.
		java.util.Map<String, QuestDefinition> merged = new java.util.HashMap<>();
		merged.putAll(new WikiDataFetcher(new com.google.gson.Gson()).fetchQuests());
		merged.putAll(data.getQuests());

		for (QuestDefinition q : data.getQuests().values())
		{
			for (String prereqId : q.getPrerequisiteQuestIds())
			{
				assertTrue(
					"Override '" + q.getId() + "' has unresolved prereq id: " + prereqId,
					merged.containsKey(prereqId));
			}
		}
	}

	@Test
	public void trainingMethodsHaveSkillAndIdSet()
	{
		for (TrainingMethod m : data.getTrainingMethods())
		{
			assertNotNull("Training method missing id", m.getId());
			assertFalse("Training method id is blank", m.getId().isEmpty());
			assertNotNull("Training method '" + m.getId() + "' missing skill", m.getSkill());
		}
	}
}

package com.questpath.data;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

import java.util.Map;
import net.runelite.api.Skill;
import org.junit.Before;
import org.junit.Test;

/**
 * Sanity checks for the bundled wiki_data.json snapshot. Catches:
 *   - JSON shape regressions (rename a field and forget to update bundled data)
 *   - Skill enum name drift (Skill.WOODCUTTING etc.)
 *   - Missing must-have quests
 *   - Dangling prereq references between wiki entries
 */
public class WikiDataFetcherTest
{
	private Map<String, QuestDefinition> quests;

	@Before
	public void setUp()
	{
		quests = new WikiDataFetcher(new com.google.gson.Gson()).fetchQuests();
	}

	@Test
	public void wikiBundleLoadsAndIsLarge()
	{
		assertNotNull(quests);
		assertTrue("Expected at least 150 quests in the wiki bundle, got " + quests.size(),
			quests.size() >= 150);
	}

	@Test
	public void coreQuestsArePresent()
	{
		// Must-haves — if these IDs disappear from the bundle, something's wrong upstream.
		// Quest Helper splits Recipe for Disaster into per-sub-quest entries
		// (recipe_for_disaster_start, ..._finale, etc.) — there's no umbrella entry,
		// so we assert the finale exists as the canonical "RFD completed" marker.
		String[] required = {
			"lunar_diplomacy",
			"the_fremennik_trials",
			"lost_city",
			"rune_mysteries",
			"shilo_village",
			"jungle_potion",
			"druidic_ritual",
			"dragon_slayer_i",
			"dragon_slayer_ii",
			"monkey_madness_i",
			"monkey_madness_ii",
			"recipe_for_disaster_finale",
			"cooks_assistant"
		};
		for (String id : required)
		{
			assertNotNull("Required quest missing from wiki bundle: " + id, quests.get(id));
		}
	}

	@Test
	public void prereqsResolveToBundleQuests()
	{
		for (QuestDefinition q : quests.values())
		{
			if (q.getPrerequisiteQuestIds() == null)
			{
				continue;
			}
			for (String prereq : q.getPrerequisiteQuestIds())
			{
				assertTrue(
					"Quest '" + q.getId() + "' references unknown prereq '" + prereq + "'",
					quests.containsKey(prereq));
			}
		}
	}

	@Test
	public void skillRequirementsUseValidEnumValues()
	{
		// Gson would fail to deserialize unknown Skill names, so reaching here proves
		// every key in skillRequirements is a real Skill. Belt-and-suspenders check that
		// at least one quest has at least one skill req.
		boolean foundOne = false;
		for (QuestDefinition q : quests.values())
		{
			Map<Skill, Integer> reqs = q.getSkillRequirements();
			if (reqs == null || reqs.isEmpty())
			{
				continue;
			}
			for (Skill s : reqs.keySet())
			{
				assertNotNull(s);
			}
			foundOne = true;
		}
		assertTrue("Expected at least one quest in the wiki bundle to have a skill requirement", foundOne);
	}

	@Test
	public void displayNamesPopulated()
	{
		for (QuestDefinition q : quests.values())
		{
			assertNotNull(q.getDisplayName());
			assertFalse("Empty displayName for id " + q.getId(), q.getDisplayName().isEmpty());
		}
	}

	@Test
	public void lunarDiplomacyHasMembersFlag()
	{
		// Note: questPointReward isn't extracted from Quest Helper source (it lives in
		// per-quest getQuestPointReward() methods we don't parse), so we only verify
		// the bundle correctly tags Lunar Diplomacy as members-only.
		QuestDefinition lunar = quests.get("lunar_diplomacy");
		assertNotNull(lunar);
		assertTrue("Lunar Diplomacy should be members", lunar.isMembers());
	}
}

package com.questpath;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class QuestPathPluginTest
{
	public static void main(String[] args) throws Exception
