	/**
	 * Wraps a child panel so its maximum size hugs its preferred height, keeping
	 * BoxLayout.Y_AXIS from over-stretching when the scroll viewport has slack.
	 */
	private static JPanel tightWrap(JPanel inner)
	{
		JPanel wrap = new JPanel()
		{
			@Override
			public Dimension getMaximumSize()
			{
				Dimension pref = getPreferredSize();
				return new Dimension(Integer.MAX_VALUE, pref.height);
			}
		};
		wrap.setLayout(new BorderLayout());
		wrap.setBackground(ColorScheme.DARK_GRAY_COLOR);
		wrap.setAlignmentX(Component.LEFT_ALIGNMENT);
		wrap.add(inner, BorderLayout.CENTER);
		return wrap;
	}

	// ----- Render -------------------------------------------------------------

	private void renderPlan(Plan plan)
	{
		summaryLabel.setText(String.format(
			"<html><b>%d</b> quest · <b>%d</b> train · <b>%d</b> gap"
				+ "  ~%.1f hr · %s gp</html>",
			plan.getQuestStepCount(),
			plan.getTrainingStepCount(),
			plan.getSkillGateStepCount(),
			plan.getTotalEstimatedHours(),
			formatGp(plan.getTotalEstimatedGpCost())));

		// One snapshot drives the info card, skill reqs, and dep tree — keeps them
		// consistent and avoids three live reads of the client-thread state.
		PlayerState state = gameStateReader.snapshot();
		QuestDefinition target = repository.getQuest(plan.getTargetQuestId());
		questInfoCard.render(target, state);
		skillReqsPanel.render(target, state);

		DependencyGraph graph = DependencyGraph.build(repository, plan.getTargetQuestId(), state);
		dependencyTree.render(graph, plan.getTargetQuestId());

		stepsContainer.removeAll();
		if (plan.getSteps().isEmpty())
		{
			stepsContainer.add(messageCard("Already complete.", ColorScheme.PROGRESS_COMPLETE_COLOR));
		}
		else
		{
			int i = 1;
			for (PlanStep step : plan.getSteps())
			{
				stepsContainer.add(stepCard(i++, step));
				stepsContainer.add(Box.createRigidArea(new Dimension(0, 6)));
			}
		}
		stepsContainer.revalidate();
		stepsContainer.repaint();
	}

	private static JPanel stepCard(int index, PlanStep step)
	{
		JPanel card = new JPanel();
		card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		card.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 3, 0, 0, accentFor(step.getType())),
			BorderFactory.createEmptyBorder(6, 8, 6, 8)));
		card.setAlignmentX(Component.LEFT_ALIGNMENT);

		// HTML wrap so long names (e.g. "The Depths Of Despair") don't clip past
		// the right edge. 170px = 225 sidebar - 20 panel margin - 3 left rail
		// - 16 horizontal card padding - room for JLabel internals.
		JLabel headline = new JLabel("<html><body style='width:170px'>"
			+ index + ".&nbsp;&nbsp;" + escapeHtml(step.getTitle())
			+ "</body></html>");
		headline.setFont(headline.getFont().deriveFont(Font.BOLD));
		headline.setForeground(Color.WHITE);
		headline.setAlignmentX(Component.LEFT_ALIGNMENT);
		card.add(headline);

		if (step.getSubtitle() != null && !step.getSubtitle().isEmpty())
		{
			JLabel sub = new JLabel("<html>" + step.getSubtitle() + "</html>");
			sub.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			sub.setAlignmentX(Component.LEFT_ALIGNMENT);
			card.add(sub);
		}
		if (step.getReasoning() != null && !step.getReasoning().isEmpty())
		{
			JLabel reason = new JLabel("<html><i>" + step.getReasoning() + "</i></html>");
			reason.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			reason.setAlignmentX(Component.LEFT_ALIGNMENT);
			card.add(reason);
		}
		return card;
	}

	private static JPanel messageCard(String message, Color accent)
	{
		JPanel card = new JPanel(new BorderLayout());
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		card.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 3, 0, 0, accent),
			BorderFactory.createEmptyBorder(6, 8, 6, 8)));
		card.setAlignmentX(Component.LEFT_ALIGNMENT);

		JLabel label = new JLabel(message);
		label.setForeground(Color.WHITE);
		label.setFont(label.getFont().deriveFont(Font.BOLD));
		card.add(label, BorderLayout.CENTER);
		return card;
	}

	private static Color accentFor(PlanStepType type)
	{
		switch (type)
		{
			case QUEST:
				return new Color(100, 180, 255);
			case TRAINING:
				return ColorScheme.BRAND_ORANGE;
			case SKILL_GATE:
				return ColorScheme.PROGRESS_ERROR_COLOR;
			default:
				return ColorScheme.LIGHT_GRAY_COLOR;
		}
	}

	/** Minimal HTML escape so quest titles with special chars (e.g. "Romeo &amp; Juliet")
	 *  don't break our HTML-wrapped labels. */
	private static String escapeHtml(String s)
	{
		if (s == null) return "";
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	private static String formatGp(double gp)
	{
		if (gp == 0)
		{
			return "0";
		}
		String sign = gp > 0 ? "-" : "+";
		double abs = Math.abs(gp);
		if (abs >= 1_000_000)
		{
			return sign + String.format("%.1fm", abs / 1_000_000);
		}
		if (abs >= 1_000)
		{
			return sign + String.format("%.0fk", abs / 1_000);
		}
		return sign + String.format("%.0f", abs);
	}

}

package com.questpath;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(QuestPathConfig.GROUP)
public interface QuestPathConfig extends Config
{
	String GROUP = "questpath";

	String TARGET_QUEST_KEY = "targetQuestId";
	String FILTER_MODE_KEY = "filterMode";
	String DIFFICULTY_FILTER_KEY = "difficultyFilter";
	String SORT_MODE_KEY = "sortMode";
	String TIME_WEIGHT_KEY = "timeWeight";
	String GP_WEIGHT_KEY = "gpWeight";
	String AFK_WEIGHT_KEY = "afkWeight";
	String HELP_EXPANDED_KEY = "helpExpanded";

	enum FilterMode
	{
		ALL("Show all"),
		QUEST("Quest"),
		MINIQUEST("Miniquest"),
		ACHIEVEMENT_DIARY("Achievement diary"),
		FREE_TO_PLAY("Free-to-Play"),
		MEMBERS("Members"),
		MEETS_REQS("Meets requirements");

		private final String label;
		FilterMode(String label) { this.label = label; }
		public String getLabel() { return label; }
		@Override public String toString() { return label; }
	}

	enum DifficultyFilter
	{
		ALL("All difficulties"),
		NOVICE("Novice"),
		INTERMEDIATE("Intermediate"),
		EXPERIENCED("Experienced"),
		MASTER("Master"),
		GRANDMASTER("Grandmaster"),
		SPECIAL("Special");

		private final String label;
		DifficultyFilter(String label) { this.label = label; }
		public String getLabel() { return label; }
		@Override public String toString() { return label; }
	}

	enum SortMode
	{
		A_Z("A → Z"),
		Z_A("Z → A"),
		QP_DESC("Quest Points ↓"),
		QP_ASC("Quest Points ↑");

		private final String label;
		SortMode(String label) { this.label = label; }
		public String getLabel() { return label; }
		@Override public String toString() { return label; }
	}

	@ConfigItem(
		keyName = TARGET_QUEST_KEY,
		name = "Target quest",
		description = "The quest you're trying to reach. Persisted across sessions; usually changed via the sidebar dropdown rather than this field."
	)
	default String targetQuestId()
	{
		return "lunar_diplomacy";
	}

	@ConfigItem(
		keyName = FILTER_MODE_KEY,
		name = "Filter mode",
		description = "Which quests to show in the target dropdown."
	)
	default FilterMode filterMode()
	{
		return FilterMode.ALL;
	}

	@ConfigItem(
		keyName = DIFFICULTY_FILTER_KEY,
		name = "Difficulty filter",
		description = "Restrict the target dropdown to a specific quest difficulty band."
	)
	default DifficultyFilter difficultyFilter()
	{
		return DifficultyFilter.ALL;
	}

	@ConfigItem(
		keyName = SORT_MODE_KEY,
		name = "Sort order",
		description = "How the target dropdown is ordered."
	)
	default SortMode sortMode()
	{
		return SortMode.A_Z;
	}

	@ConfigItem(
		keyName = TIME_WEIGHT_KEY,
		name = "Time preference",
		description = "How much to weight training method speed (0 = ignore, 10 = heavy preference). Higher = pick fastest methods."
	)
	default int timeWeight()
	{
		return 5;
	}

	@ConfigItem(
		keyName = GP_WEIGHT_KEY,
		name = "GP preference",
		description = "How much to weight training method profitability (0 = ignore, 10 = heavy preference). Higher = pick methods that earn / lose less GP."
	)
	default int gpWeight()
	{
		return 5;
	}

	@ConfigItem(
		keyName = AFK_WEIGHT_KEY,
		name = "AFK preference",
		description = "How much to weight how AFK-friendly methods are (0 = ignore, 10 = heavy preference). Higher = pick low-attention methods."
	)
	default int afkWeight()
	{
		return 5;
	}

	@ConfigItem(
		keyName = HELP_EXPANDED_KEY,
		name = "Help panel expanded",
		description = "Whether the Help & Tips panel in the sidebar starts expanded. Toggled by clicking the panel header."
	)
	default boolean helpExpanded()
	{
		// First-launch: expanded so the user can read the legend. They collapse it
		// once they're oriented and the choice persists.
		return true;
	}

	@ConfigItem(
		keyName = "logSkillsOnLogin",
		name = "Log skill snapshot on login",
		description = "Dev toggle: prints all skill levels to the console when you log in."
	)
	default boolean logSkillsOnLogin()
	{
		return false;
	}
}

package com.questpath;

import com.google.inject.Provides;
import com.questpath.data.QuestRepository;
import com.questpath.game.GameStateReader;
import com.questpath.game.PlayerState;
import com.questpath.planner.PathPlanner;
import com.questpath.planner.Plan;
import com.questpath.planner.PlanStep;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "QuestPath",
	description = "Quest prerequisite visualizer and planner",
	tags = {"quest", "planning", "prerequisites", "skills"}
)
public class QuestPathPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private QuestPathConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private QuestRepository questRepository;

	@Inject
	private GameStateReader gameStateReader;

	@Inject
	private PathPlanner pathPlanner;

	private QuestPathPanel panel;
	private NavigationButton navButton;

	@Override
	protected void startUp() throws Exception
	{
		log.info("QuestPath starting up");
		log.info("QuestPath data layer: {} quests, {} training methods loaded",
			questRepository.questCount(), questRepository.trainingMethodCount());

		// Build the panel; it owns its own initial plan render via the constructor's
		// selectTarget() call. We just hand it the deps and the persisted target id.
		panel = new QuestPathPanel(
			questRepository,
			gameStateReader,
			pathPlanner,
			configManager,
			config,
			config.targetQuestId());

		// Also dump the initial plan to console for log-driven debugging.
		Plan initial = pathPlanner.plan(config.targetQuestId(), PlayerState.empty());
		dumpPlanToConsole(initial);

		final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/icon.png");

		navButton = NavigationButton.builder()
			.tooltip("QuestPath")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);
	}

	@Override
	protected void shutDown() throws Exception
	{
		log.info("QuestPath shutting down");
		clientToolbar.removeNavigation(navButton);
		panel = null;
		navButton = null;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged gameStateChanged)
	{
		if (gameStateChanged.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		if (config.logSkillsOnLogin())
		{
			logAllSkillLevels();
		}
		// Refresh the panel against live state.
		if (panel != null)
		{
			panel.refresh();
		}
	}

	/**
	 * When the target quest config changes (either via the panel dropdown or the
	 * RuneLite config UI), refresh the panel so both views stay in sync. Panel
	 * sets-then-refreshes itself on dropdown change, so this catches the
	 * "external edit" case primarily.
	 */
	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!QuestPathConfig.GROUP.equals(event.getGroup()) || panel == null)
		{
			return;
		}
		String key = event.getKey();
		if (QuestPathConfig.TARGET_QUEST_KEY.equals(key)
			|| QuestPathConfig.FILTER_MODE_KEY.equals(key)
			|| QuestPathConfig.DIFFICULTY_FILTER_KEY.equals(key)
			|| QuestPathConfig.SORT_MODE_KEY.equals(key)
			|| QuestPathConfig.TIME_WEIGHT_KEY.equals(key)
			|| QuestPathConfig.GP_WEIGHT_KEY.equals(key)
			|| QuestPathConfig.AFK_WEIGHT_KEY.equals(key))
		{
			panel.refresh();
		}
	}

	private void logAllSkillLevels()
	{
		log.info("=== QuestPath: skill snapshot ===");
		for (Skill skill : Skill.values())
		{
			if (skill == Skill.OVERALL)
			{
				continue;
			}
			int level = client.getRealSkillLevel(skill);
			int xp = client.getSkillExperience(skill);
			log.info("  {} — level {} ({} xp)", skill.getName(), level, xp);
		}
		log.info("=== end snapshot ===");
	}

	private static void dumpPlanToConsole(Plan plan)
	{
		log.info("=== QuestPath plan: {} ===", plan.getTargetQuestDisplayName());
		log.info("Steps: {} quest, {} training, {} skill-gate    Total: ~{} hr   GP: {}",
			plan.getQuestStepCount(), plan.getTrainingStepCount(), plan.getSkillGateStepCount(),
			String.format("%.1f", plan.getTotalEstimatedHours()),
			String.format("%.0f", plan.getTotalEstimatedGpCost()));
		int i = 1;
		for (PlanStep step : plan.getSteps())
		{
			log.info("  {}. [{}] {}", i++, step.getType(), step.getTitle());
			if (step.getSubtitle() != null && !step.getSubtitle().isEmpty())
			{
				log.info("     {}", step.getSubtitle());
			}
		}
		log.info("=== end plan ===");
	}

	@Provides
	QuestPathConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(QuestPathConfig.class);
	}
}

package com.questpath.ui;

import com.questpath.data.QuestDefinition;
import com.questpath.game.PlayerState;
import com.questpath.game.QuestStatus;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Font;
import java.awt.Insets;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.util.LinkBrowser;

/**
 * Quest Helper-style header card for the currently-selected target quest.
 *
 * Layout (top → bottom):
 *   - Orange title bar with the quest's display name
 *   - Status pill ("Not Started" / "In Progress" / "Complete") with traffic-light color
 *   - Inline badges: Members / F2P, difficulty, QP reward
 *   - Action row: [Open in Quest Helper] (only if QH installed) [Wiki]
 *
 * The card is self-contained; the panel just calls {@link #render(QuestDefinition, QuestStatus)}
 * whenever the target or game state changes.
 */
@Slf4j
public class QuestInfoCard extends JPanel
{
	private static final Color TITLE_BG = ColorScheme.BRAND_ORANGE;
	private static final Color CARD_BG = ColorScheme.DARKER_GRAY_COLOR;
	private static final Color BADGE_BG = ColorScheme.DARK_GRAY_HOVER_COLOR;
	private static final Color STATUS_DONE = ColorScheme.PROGRESS_COMPLETE_COLOR;
	private static final Color STATUS_PROGRESS = ColorScheme.BRAND_ORANGE;
	private static final Color STATUS_NOT_STARTED = ColorScheme.PROGRESS_ERROR_COLOR;

	private final JLabel titleLabel = new JLabel(" ");
	private final JLabel statusLabel = new JLabel(" ");
	private final JPanel badgeRow = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0));
	private final JButton wikiButton = new JButton("Open Wiki");

	// Held so the buttons' action listeners can target the right quest.
	private QuestDefinition currentQuest;

	public QuestInfoCard()
	{
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(CARD_BG);
		setAlignmentX(Component.LEFT_ALIGNMENT);
		setBorder(BorderFactory.createMatteBorder(0, 0, 1, 0, ColorScheme.BORDER_COLOR));

		add(buildTitleBar());
		add(buildBodyPanel());
	}

	/** Stay at preferred height in BoxLayout.Y_AXIS parents (tight packing). */
	@Override
	public Dimension getMaximumSize()
	{
		Dimension pref = getPreferredSize();
		return new Dimension(Integer.MAX_VALUE, pref.height);
	}

	// ----- public API ----------------------------------------------------------

	public void render(QuestDefinition quest, QuestStatus status)
	{
		this.currentQuest = quest;

		if (quest == null)
		{
			titleLabel.setText("No quest selected");
			statusLabel.setText(" ");
			statusLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			badgeRow.removeAll();
			wikiButton.setEnabled(false);
			revalidate();
			repaint();
			return;
		}

		titleLabel.setText(quest.getDisplayName());

		statusLabel.setText(statusText(status));
		statusLabel.setForeground(statusColor(status));

		badgeRow.removeAll();
		badgeRow.add(badge(quest.isMembers() ? "Members" : "Free-to-play",
			quest.isMembers() ? new Color(190, 100, 100) : new Color(110, 160, 110)));
		if (quest.getDifficulty() != null && !quest.getDifficulty().isEmpty())
		{
			badgeRow.add(badge(prettyDifficulty(quest.getDifficulty()), null));
		}
		if (quest.getQuestPointReward() > 0)
		{
			badgeRow.add(badge(quest.getQuestPointReward() + " QP", null));
		}

		wikiButton.setEnabled(quest.getWikiUrl() != null && !quest.getWikiUrl().isEmpty());

		revalidate();
		repaint();
	}

	// ----- layout helpers ------------------------------------------------------

	private JPanel buildTitleBar()
	{
		JPanel bar = new JPanel(new BorderLayout());
		bar.setBackground(TITLE_BG);
		bar.setAlignmentX(Component.LEFT_ALIGNMENT);
		bar.setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 8));
		bar.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));

		titleLabel.setForeground(Color.WHITE);
		titleLabel.setFont(titleLabel.getFont().deriveFont(Font.BOLD, 16f));
		bar.add(titleLabel, BorderLayout.WEST);
		return bar;
	}

	private JPanel buildBodyPanel()
	{
		JPanel body = new JPanel();
		body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
		body.setBackground(CARD_BG);
		body.setAlignmentX(Component.LEFT_ALIGNMENT);
		body.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

		statusLabel.setFont(statusLabel.getFont().deriveFont(Font.BOLD, 14f));
		statusLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
		body.add(statusLabel);
		body.add(Box.createRigidArea(new Dimension(0, 6)));

		badgeRow.setBackground(CARD_BG);
		badgeRow.setAlignmentX(Component.LEFT_ALIGNMENT);
		badgeRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
		body.add(badgeRow);
		body.add(Box.createRigidArea(new Dimension(0, 8)));

		body.add(buildActionRow());
		return body;
	}

	private JPanel buildActionRow()
	{
		JPanel row = new JPanel();
		row.setLayout(new BoxLayout(row, BoxLayout.X_AXIS));
		row.setBackground(CARD_BG);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		styleActionButton(wikiButton);
		wikiButton.addActionListener(e -> handleOpenWiki());
		row.add(wikiButton);

		row.add(Box.createHorizontalGlue());
		return row;
	}

	private static void styleActionButton(JButton button)
	{
		button.setMargin(new Insets(2, 8, 2, 8));
		button.setFocusable(false);
	}

	private static JLabel badge(String text, Color tint)
	{
		JLabel label = new JLabel(text);
		label.setOpaque(true);
		label.setBackground(tint == null ? BADGE_BG : tint);
		label.setForeground(Color.WHITE);
		label.setFont(label.getFont().deriveFont(Font.BOLD, 12f));
		label.setBorder(BorderFactory.createEmptyBorder(3, 7, 3, 7));
		return label;
	}

	private void handleOpenWiki()
	{
		if (currentQuest == null || currentQuest.getWikiUrl() == null)
		{
			return;
		}
		LinkBrowser.browse(currentQuest.getWikiUrl());
	}

	// ----- formatting ----------------------------------------------------------

	private static String statusText(QuestStatus status)
	{
		if (status == null)
		{
			return "Status unknown";
		}
		switch (status)
		{
			case DONE:
				return "✓ Complete";
			case IN_PROGRESS:
				return "● In Progress";
			case NOT_STARTED:
			default:
				return "○ Not Started";
		}
	}

	private static Color statusColor(QuestStatus status)
	{
		if (status == null)
		{
			return ColorScheme.LIGHT_GRAY_COLOR;
		}
		switch (status)
		{
			case DONE:
				return STATUS_DONE;
			case IN_PROGRESS:
				return STATUS_PROGRESS;
			case NOT_STARTED:
			default:
				return STATUS_NOT_STARTED;
		}
	}

	private static String prettyDifficulty(String raw)
	{
		// "GRANDMASTER" → "Grandmaster", "ACHIEVEMENT_DIARY" → "Diary"
		if ("ACHIEVEMENT_DIARY".equals(raw))
		{
			return "Diary";
		}
		if ("MINIQUEST".equals(raw))
		{
			return "Miniquest";
		}
		String lower = raw.toLowerCase().replace('_', ' ');
		return Character.toUpperCase(lower.charAt(0)) + lower.substring(1);
	}

	/** Convenience overload for callers that have a PlayerState on hand. */
	public void render(QuestDefinition quest, PlayerState state)
	{
		QuestStatus status = (quest == null || state == null)
			? null
			: state.getQuestStatus(quest.getId());
		render(quest, status);
	}
}

