package com.questpath.ui;

import com.questpath.data.QuestDefinition;
import com.questpath.game.PlayerState;
import com.questpath.game.QuestStatus;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.List;
import java.util.Map;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.api.Skill;
import net.runelite.client.ui.ColorScheme;

/**
 * Quest Helper-style scrollable quest picker. One row per quest: name on the
 * left, status dot, chevron on the right. Click any row to fire the
 * {@link QuestSelectionListener}; hovering highlights the row.
 *
 * Status dot meanings (best-effort against the player snapshot):
 *   green  — quest already DONE
 *   blue   — all prereqs + skill walls met, ready to start now
 *   orange — skill walls unmet
 *   red    — prereq quest not yet done
 *
 * The whole panel hugs its preferred height so the wrapping JScrollPane in
 * {@link com.questpath.QuestPathPanel} controls the scroll viewport, not us.
 */
public class QuestListPanel extends JPanel
{
	private static final Color DOT_DONE = ColorScheme.PROGRESS_COMPLETE_COLOR;
	private static final Color DOT_READY = new Color(100, 180, 255);
	private static final Color DOT_BLOCKED_QUEST = ColorScheme.PROGRESS_ERROR_COLOR;
	private static final Color DOT_BLOCKED_SKILL = ColorScheme.BRAND_ORANGE;

	private static final int ROW_MIN_HEIGHT = 28;
	private static final int CHEVRON_FONT_SIZE = 14;

	@FunctionalInterface
	public interface QuestSelectionListener
	{
		void onQuestSelected(String questId);
	}

	private final QuestSelectionListener listener;

	public QuestListPanel(QuestSelectionListener listener)
	{
		this.listener = listener;
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setAlignmentX(Component.LEFT_ALIGNMENT);
	}

	/** Hug content height so the wrapping scroll pane drives the scrollbar. */
	@Override
	public Dimension getMaximumSize()
	{
		Dimension pref = getPreferredSize();
		return new Dimension(Integer.MAX_VALUE, pref.height);
	}

	/**
	 * Replace the rendered rows with the given quests. The list is rendered in
	 * the order received — caller controls sort.
	 */
	public void render(List<QuestDefinition> quests, PlayerState state)
	{
		removeAll();

		if (quests.isEmpty())
		{
			add(emptyState());
			revalidate();
			repaint();
			return;
		}

		for (QuestDefinition q : quests)
		{
			add(buildRow(q, state));
		}
		revalidate();
		repaint();
	}

	// ----- row builders -------------------------------------------------------

	private JPanel buildRow(QuestDefinition quest, PlayerState state)
	{
		JPanel row = new JPanel();
		row.setLayout(new BoxLayout(row, BoxLayout.X_AXIS));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 0, 1, 0, ColorScheme.DARK_GRAY_COLOR),
			BorderFactory.createEmptyBorder(6, 8, 6, 8)));
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, ROW_MIN_HEIGHT + 6));
		row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

		// Status dot (8px circle drawn as colored panel — cheap and crisp at sidebar sizes).
		Color dotColor = statusDot(quest, state);
		JPanel dot = new JPanel();
		dot.setBackground(dotColor);
		dot.setPreferredSize(new Dimension(8, 8));
		dot.setMinimumSize(new Dimension(8, 8));
		dot.setMaximumSize(new Dimension(8, 8));
		dot.setAlignmentY(Component.CENTER_ALIGNMENT);
		row.add(dot);
		row.add(Box.createRigidArea(new Dimension(8, 0)));

		// Quest name — HTML wraps long names cleanly inside the 225px sidebar.
		JLabel name = new JLabel(
			"<html><body style='width:150px'>" + escapeHtml(quest.getDisplayName()) + "</body></html>");
		name.setForeground(Color.WHITE);
		name.setFont(name.getFont().deriveFont(Font.PLAIN, 14f));
		name.setAlignmentY(Component.CENTER_ALIGNMENT);
		row.add(name);

		row.add(Box.createHorizontalGlue());

		JLabel chevron = new JLabel("›");
		chevron.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		chevron.setFont(chevron.getFont().deriveFont(Font.BOLD, (float) CHEVRON_FONT_SIZE));
		chevron.setAlignmentY(Component.CENTER_ALIGNMENT);
		row.add(chevron);

		MouseAdapter handler = new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (listener != null)
				{
					listener.onQuestSelected(quest.getId());
				}
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				row.setBackground(ColorScheme.DARK_GRAY_HOVER_COLOR);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			}
		};
		row.addMouseListener(handler);
		// Children swallow events by default — install on each so hovering the
		// label or chevron doesn't break the highlight.
		name.addMouseListener(handler);
		chevron.addMouseListener(handler);
		dot.addMouseListener(handler);

		return row;
	}

	private static JPanel emptyState()
	{
		JPanel panel = new JPanel();
		panel.setLayout(new BoxLayout(panel, BoxLayout.X_AXIS));
		panel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);
		panel.setBorder(BorderFactory.createEmptyBorder(12, 8, 12, 8));

		JLabel label = new JLabel("No quests match. Try clearing search or filters.");
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setFont(label.getFont().deriveFont(Font.ITALIC, 12f));
		panel.add(label);
		return panel;
	}

	// ----- status -------------------------------------------------------------

	/**
	 * Best-effort status color, mirroring NodeStatus colors used in the
	 * dependency tree so the legend is consistent across views.
	 */
	private static Color statusDot(QuestDefinition quest, PlayerState state)
	{
		if (state == null)
		{
			return DOT_READY;
		}
		QuestStatus status = state.getQuestStatus(quest.getId());
		if (status == QuestStatus.DONE)
		{
			return DOT_DONE;
		}

		// Direct (non-transitive) check — fast and good enough for the list view.
		if (quest.getPrerequisiteQuestIds() != null)
		{
			for (String prereqId : quest.getPrerequisiteQuestIds())
			{
				if (state.getQuestStatus(prereqId) != QuestStatus.DONE)
				{
					return DOT_BLOCKED_QUEST;
				}
			}
		}
		if (quest.getSkillRequirements() != null)
		{
			for (Map.Entry<Skill, Integer> req : quest.getSkillRequirements().entrySet())
			{
				if (state.getSkillLevel(req.getKey()) < req.getValue())
				{
					return DOT_BLOCKED_SKILL;
				}
			}
		}
		return DOT_READY;
	}

	private static String escapeHtml(String s)
	{
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}
}

package com.questpath.ui;

import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;

/**
 * Collapsible "Help &amp; Tips" panel — color legend + slider preset
 * recommendations. Sits at the top of the body so first-time users get
 * oriented; click the header to collapse once they know the codes.
 *
 * The collapsed/expanded state is owned by the parent (persisted to config),
 * so this component only renders + reports clicks via its toggle callback.
 */
public class HelpPanel extends JPanel
{
	// Re-declared from DependencyTreePanel / step cards so the legend swatches
	// match exactly what the user sees elsewhere. Keep in sync if those change.
	private static final Color COLOR_DONE = ColorScheme.PROGRESS_COMPLETE_COLOR;
	private static final Color COLOR_READY = new Color(100, 180, 255);
	private static final Color COLOR_BLOCKED_QUEST = ColorScheme.PROGRESS_ERROR_COLOR;
	private static final Color COLOR_BLOCKED_SKILL = ColorScheme.BRAND_ORANGE;

	private final JLabel headerLabel = new JLabel();
	private final JPanel body = new JPanel();
	private final Consumer<Boolean> onToggle;

	private boolean expanded;

	public HelpPanel(boolean initialExpanded, Consumer<Boolean> onToggle)
	{
		this.expanded = initialExpanded;
		this.onToggle = onToggle;

		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setAlignmentX(Component.LEFT_ALIGNMENT);

		add(buildHeader());
		buildBody();
		add(body);
		applyExpanded();
	}

	/** Hug content height so BoxLayout.Y_AXIS doesn't gift us blank space. */
	@Override
	public Dimension getMaximumSize()
	{
		Dimension pref = getPreferredSize();
		return new Dimension(Integer.MAX_VALUE, pref.height);
	}

	// ----- header --------------------------------------------------------------

	private JPanel buildHeader()
	{
		JPanel header = new JPanel();
		header.setLayout(new BoxLayout(header, BoxLayout.X_AXIS));
		header.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		header.setAlignmentX(Component.LEFT_ALIGNMENT);
		header.setBorder(BorderFactory.createEmptyBorder(6, 6, 6, 6));
		header.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
		header.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

		updateHeaderLabel();
		headerLabel.setFont(headerLabel.getFont().deriveFont(Font.BOLD, 14f));
		headerLabel.setForeground(ColorScheme.BRAND_ORANGE);
		header.add(headerLabel);
		header.add(Box.createHorizontalGlue());

		MouseAdapter clickToggle = new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				expanded = !expanded;
				applyExpanded();
				updateHeaderLabel();
				if (onToggle != null)
				{
					onToggle.accept(expanded);
				}
			}
		};
		header.addMouseListener(clickToggle);
		headerLabel.addMouseListener(clickToggle);

		return header;
	}

	private void updateHeaderLabel()
	{
		headerLabel.setText((expanded ? "▼ " : "▶ ") + "HELP & TIPS");
	}

	private void applyExpanded()
	{
		body.setVisible(expanded);
		revalidate();
		repaint();
	}

	// ----- body ----------------------------------------------------------------

	private void buildBody()
	{
		body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
		body.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		body.setAlignmentX(Component.LEFT_ALIGNMENT);
		body.setBorder(BorderFactory.createEmptyBorder(8, 6, 8, 6));

		body.add(subheading("Color legend"));
		body.add(legendRow(COLOR_DONE, "Done — quest finished or skill met"));
		body.add(legendRow(COLOR_READY, "Ready — all prereqs met, can start"));
		body.add(legendRow(COLOR_BLOCKED_QUEST, "Blocked — needs another quest first"));
		body.add(legendRow(COLOR_BLOCKED_SKILL, "Skill gate — needs more training"));

		body.add(Box.createRigidArea(new Dimension(0, 8)));
		body.add(subheading("Slider presets"));
		body.add(tip("Speedrunner: Time 10, GP 0, AFK 0 — ignore cost, optimize hours."));
		body.add(tip("Iron / GP-mindful: Time 5, GP 8, AFK 2 — bias toward profitable methods."));
		body.add(tip("AFK Andy: Time 2, GP 3, AFK 10 — pick what you can do while watching TV."));

		body.add(Box.createRigidArea(new Dimension(0, 8)));
		body.add(subheading("Tips"));
		body.add(tip("Click any quest in the dependency tree to collapse / expand its prereqs."));
		body.add(tip("If Quest Helper is installed, the Open in Quest Helper button hands the quest off so QH walks you through it step-by-step."));
		body.add(tip("Use the Filter dropdown to narrow the target list to F2P quests, miniquests, or only what you can start right now."));
	}

	private static JLabel subheading(String text)
	{
		JLabel label = new JLabel(text);
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setFont(label.getFont().deriveFont(Font.BOLD, 13f));
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		label.setBorder(BorderFactory.createEmptyBorder(0, 0, 4, 0));
		return label;
	}

	private static JPanel legendRow(Color swatchColor, String text)
	{
		JPanel row = new JPanel();
		row.setLayout(new BoxLayout(row, BoxLayout.X_AXIS));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setBorder(BorderFactory.createEmptyBorder(2, 0, 2, 0));
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 22));

		JPanel swatch = new JPanel();
		swatch.setBackground(swatchColor);
		swatch.setPreferredSize(new Dimension(12, 12));
		swatch.setMinimumSize(new Dimension(12, 12));
		swatch.setMaximumSize(new Dimension(12, 12));
		swatch.setAlignmentY(Component.CENTER_ALIGNMENT);
		row.add(swatch);
		row.add(Box.createRigidArea(new Dimension(8, 0)));

		JLabel label = new JLabel(text);
		label.setForeground(Color.WHITE);
		label.setFont(label.getFont().deriveFont(Font.PLAIN, 13f));
		row.add(label);
		row.add(Box.createHorizontalGlue());
		return row;
	}

	private static JLabel tip(String text)
	{
		// HTML body width keeps long tips wrapping inside the 225px sidebar.
		// 160 leaves margin: 225 - 10 outer panel border × 2 - 6 helpPanel body
		// padding × 2 - a bit for JLabel internal padding ≈ ~185 actual room,
		// and 160 is a comfortable fit at 13pt without chopping the last word.
		JLabel label = new JLabel("<html><body style='width:160px'>• " + text + "</body></html>");
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setFont(label.getFont().deriveFont(Font.PLAIN, 13f));
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		label.setBorder(BorderFactory.createEmptyBorder(2, 0, 2, 0));
		return label;
	}
}

package com.questpath.ui;

import com.questpath.planner.DependencyGraph;
import com.questpath.planner.NodeStatus;
import com.questpath.planner.QuestNode;
import com.questpath.planner.SkillGate;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.HashSet;
import java.util.Set;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;

/**
 * Replacement for the JTree dependency view. Each row is a JLabel with HTML
 * word-wrap so long quest names ("The Fremennik Trials") render fully across
 * two lines instead of getting clipped to "The Fr".
 *
 * Indentation per depth: a fixed left margin on the row's panel. Status
 * colors come from {@link NodeStatus}; skill gates use orange (unmet) or
 * green (met). Quests with children get a clickable ▼/▶ disclosure widget;
 * the panel remembers which quests are collapsed across re-renders.
 */
public class DependencyTreePanel extends JPanel
{
	private static final Color READY_COLOR = new Color(100, 180, 255);
	private static final int INDENT_PX = 12;
	private static final int FONT_SIZE = 14;
	private static final int DISCLOSURE_SLOT_PX = 18;

	/**
	 * Approximate width available for label text after subtracting the panel's
	 * borders + rail + spacer + indent. RuneLite's PluginPanel is fixed at 225px;
	 * we shave ~30px for chrome and let the HTML wrap engine do the rest.
	 */
	private static final int BASE_TEXT_WIDTH_PX = 172;

	private final Set<String> collapsedIds = new HashSet<>();

	/** Cached so click handlers can re-render without re-fetching the graph. */
	private DependencyGraph currentGraph;
	private String currentRootId;

	public DependencyTreePanel()
	{
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setAlignmentX(LEFT_ALIGNMENT);
	}

	/**
	 * Cap our height to what we actually need. Without this, the parent
	 * BoxLayout.Y_AXIS hands out leftover scroll space evenly across siblings,
	 * leaving a giant blank gap between the tree and the next section.
	 */
	@Override
	public Dimension getMaximumSize()
	{
		Dimension pref = getPreferredSize();
		return new Dimension(Integer.MAX_VALUE, pref.height);
	}

	/** Rebuild contents from the graph rooted at {@code rootQuestId}. */
	public void render(DependencyGraph graph, String rootQuestId)
	{
		this.currentGraph = graph;
		this.currentRootId = rootQuestId;
		rerender();
	}

	private void rerender()
	{
		removeAll();
		if (currentGraph == null || currentRootId == null)
		{
			revalidate();
			repaint();
			return;
		}
		appendQuest(currentGraph, currentRootId, 0, new ArrayDeque<>());
		revalidate();
		repaint();
	}

	/**
	 * @param expanding ids in the current DFS path. If we re-encounter one, we have
	 *                  a cycle (data bug) and must render a leaf instead of recursing.
	 */
	private void appendQuest(DependencyGraph graph, String questId, int depth, Deque<String> expanding)
	{
		QuestNode node = graph.getNode(questId);
		if (node == null)
		{
			add(makeRow(questId, ColorScheme.LIGHT_GRAY_COLOR, depth, NoChildren.INSTANCE, null));
			return;
		}

		// Cycle guard. With sanitized data we shouldn't ever hit this, but render a
		// flat leaf with a hint rather than blowing up if a self-loop slips through.
		if (expanding.contains(questId))
		{
			add(makeRow(node.getDisplayName() + "  (already shown)",
				ColorScheme.LIGHT_GRAY_COLOR, depth, NoChildren.INSTANCE, null));
			return;
		}

		boolean hasChildren = !node.getPrerequisiteQuestIds().isEmpty()
			|| !node.getSkillGates().isEmpty();
		boolean collapsed = collapsedIds.contains(questId);

		ChildState state = !hasChildren
			? NoChildren.INSTANCE
			: collapsed ? new Collapsed(questId) : new Expanded(questId);

		add(makeRow(node.getDisplayName(), colorFor(node.getStatus()), depth, state, this::toggleCollapse));

		if (collapsed)
		{
			return;
		}

		expanding.push(questId);
		try
		{
			// Children: prereq quests first, then skill gates.
			for (String prereqId : node.getPrerequisiteQuestIds())
			{
				appendQuest(graph, prereqId, depth + 1, expanding);
			}
			for (SkillGate gate : node.getSkillGates())
			{
				String label = String.format("%s %d → %d",
					gate.getSkill().getName(), gate.getCurrentLevel(), gate.getRequiredLevel());
				Color color = gate.isMet()
					? ColorScheme.PROGRESS_COMPLETE_COLOR
					: ColorScheme.BRAND_ORANGE;
				add(makeRow(label, color, depth + 1, NoChildren.INSTANCE, null));
			}
		}
		finally
		{
			expanding.pop();
		}
	}

	private void toggleCollapse(String questId)
	{
		if (!collapsedIds.add(questId))
		{
			collapsedIds.remove(questId);
		}
		rerender();
	}

	private static JPanel makeRow(
		String text, Color color, int depth, ChildState state, java.util.function.Consumer<String> onToggle)
	{
		JPanel row = new JPanel();
		row.setLayout(new BoxLayout(row, BoxLayout.X_AXIS));
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		row.setAlignmentX(LEFT_ALIGNMENT);

		// Indent (left empty border) + colored rail (matte border) + content padding.
		// MatteBorder auto-stretches with the row's height, including when the
		// label wraps to multiple lines. Vertical padding makes rows easier to
		// click without making the list cramped.
		row.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createEmptyBorder(2, depth * INDENT_PX, 2, 0),
			BorderFactory.createCompoundBorder(
				BorderFactory.createMatteBorder(0, 2, 0, 0, color),
				BorderFactory.createEmptyBorder(0, 4, 0, 0))));

		// Disclosure widget — fixed slot for visual alignment, populated only when
		// the row has children. The slot itself stays clickable so the user gets a
		// stable hit target column.
		JLabel disclosure = new JLabel(state.glyph(), JLabel.CENTER);
		disclosure.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		disclosure.setFont(disclosure.getFont().deriveFont(Font.BOLD, 12f));
		disclosure.setPreferredSize(new Dimension(DISCLOSURE_SLOT_PX, 18));
		disclosure.setMaximumSize(new Dimension(DISCLOSURE_SLOT_PX, 18));
		disclosure.setMinimumSize(new Dimension(DISCLOSURE_SLOT_PX, 18));
		disclosure.setAlignmentY(Component.TOP_ALIGNMENT);
		row.add(disclosure);
		row.add(Box.createRigidArea(new Dimension(4, 0)));

		// JLabel HTML wraps to <body width=N> only — without explicit width,
		// it computes preferred size single-line and gets clipped. Width
		// shrinks with depth to keep deeply-nested rows from overflowing.
		int textWidth = Math.max(70, BASE_TEXT_WIDTH_PX - depth * INDENT_PX);
		JLabel label = new JLabel(
			"<html><body style='width:" + textWidth + "px'>"
				+ escapeHtml(text)
				+ "</body></html>");
		label.setFont(label.getFont().deriveFont(Font.PLAIN, (float) FONT_SIZE));
		label.setForeground(color);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		label.setAlignmentY(Component.TOP_ALIGNMENT);
		label.setToolTipText(text);
		row.add(label);
		row.add(Box.createHorizontalGlue());

		// Whole-row click + hover effect for quest nodes with children. Clicking
		// the row, the label, the disclosure, or the empty space all toggle.
		if (state.questId() != null && onToggle != null)
		{
			final String capturedId = state.questId();
			MouseAdapter rowMouseHandler = new MouseAdapter()
			{
				@Override
				public void mouseClicked(MouseEvent e)
				{
					onToggle.accept(capturedId);
				}

				@Override
				public void mouseEntered(MouseEvent e)
				{
					row.setBackground(ColorScheme.DARKER_GRAY_HOVER_COLOR);
				}

				@Override
				public void mouseExited(MouseEvent e)
				{
					row.setBackground(ColorScheme.DARK_GRAY_COLOR);
				}
			};
			row.addMouseListener(rowMouseHandler);
			label.addMouseListener(rowMouseHandler);
			disclosure.addMouseListener(rowMouseHandler);
			row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
			label.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
			disclosure.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		}

		return row;
	}

	private static String escapeHtml(String s)
	{
		return s
			.replace("&", "&amp;")
			.replace("<", "&lt;")
			.replace(">", "&gt;");
	}

	private static Color colorFor(NodeStatus status)
	{
		switch (status)
		{
			case DONE:
				return ColorScheme.PROGRESS_COMPLETE_COLOR;
			case READY:
				return READY_COLOR;
			case BLOCKED_BY_SKILL:
				return ColorScheme.BRAND_ORANGE;
			case BLOCKED_BY_QUEST:
				return ColorScheme.PROGRESS_ERROR_COLOR;
			default:
				return ColorScheme.LIGHT_GRAY_COLOR;
		}
	}

	// ----- Disclosure state ---------------------------------------------------

	private interface ChildState
	{
		String glyph();
		String questId();
	}

	private static final class NoChildren implements ChildState
	{
		static final NoChildren INSTANCE = new NoChildren();

		@Override public String glyph() { return " "; }
		@Override public String questId() { return null; }
	}

	private static final class Expanded implements ChildState
	{
		private final String questId;
		Expanded(String questId) { this.questId = questId; }
		@Override public String glyph() { return "▼"; }
		@Override public String questId() { return questId; }
	}

	private static final class Collapsed implements ChildState
	{
		private final String questId;
		Collapsed(String questId) { this.questId = questId; }
		@Override public String glyph() { return "▶"; }
		@Override public String questId() { return questId; }
	}
}

package com.questpath.ui;

import com.questpath.data.QuestDefinition;
import com.questpath.game.PlayerState;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.api.Skill;
import net.runelite.client.ui.ColorScheme;

/**
 * Quest Helper-style "General requirements" panel — one row per skill /
 * QP gate, color-coded green when the player meets it and red when they
 * don't. Hidden entirely when the target has no requirements.
 *
 * Render contract: caller invokes {@link #render(QuestDefinition, PlayerState)}
 * after each plan refresh; we rebuild the row list and toggle visibility.
 */
public class SkillRequirementsPanel extends JPanel
{
	private static final Color MET = new Color(110, 200, 110);
	private static final Color UNMET = new Color(220, 100, 100);
	private static final int ROW_HEIGHT = 24;

	private final JPanel rowsContainer = new JPanel();

	public SkillRequirementsPanel()
	{
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setAlignmentX(Component.LEFT_ALIGNMENT);

		rowsContainer.setLayout(new BoxLayout(rowsContainer, BoxLayout.Y_AXIS));
		rowsContainer.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		rowsContainer.setAlignmentX(Component.LEFT_ALIGNMENT);
		rowsContainer.setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 8));

		add(rowsContainer);

		setVisible(false);
	}

	/** Hug content height — see DependencyTreePanel.getMaximumSize() for rationale. */
	@Override
	public Dimension getMaximumSize()
	{
		Dimension pref = getPreferredSize();
		return new Dimension(Integer.MAX_VALUE, pref.height);
	}

	public void render(QuestDefinition quest, PlayerState state)
	{
		rowsContainer.removeAll();

		if (quest == null)
		{
			setVisible(false);
			return;
		}

		List<Row> rows = new ArrayList<>();

		Map<Skill, Integer> skillReqs = quest.getSkillRequirements();
		if (skillReqs != null)
		{
			for (Map.Entry<Skill, Integer> req : skillReqs.entrySet())
			{
				int have = state == null ? 1 : state.getSkillLevel(req.getKey());
				rows.add(new Row(req.getKey().getName(), req.getValue(), have));
			}
		}
		// Sort by skill name for stable display.
		rows.sort(Comparator.comparing(r -> r.label));

		int qpReq = quest.getQuestPointRequirement();
		if (qpReq > 0)
		{
			int haveQp = state == null ? 0 : state.getQuestPoints();
			rows.add(0, new Row("Quest Points", qpReq, haveQp));
		}

		if (rows.isEmpty())
		{
			setVisible(false);
			revalidate();
			repaint();
			return;
		}

		for (Row r : rows)
		{
			rowsContainer.add(buildRow(r));
		}
		setVisible(true);
		revalidate();
		repaint();
	}

	private static JLabel buildRow(Row row)
	{
		boolean met = row.have >= row.need;
		String text = String.format("%s %d  (you have %d)", row.label, row.need, row.have);
		JLabel label = new JLabel(text);
		label.setForeground(met ? MET : UNMET);
		label.setFont(label.getFont().deriveFont(met ? Font.PLAIN : Font.BOLD, 14f));
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		label.setMaximumSize(new Dimension(Integer.MAX_VALUE, ROW_HEIGHT));
		label.setBorder(BorderFactory.createEmptyBorder(1, 0, 1, 0));
		return label;
	}

	private static final class Row
	{
		final String label;
		final int need;
		final int have;

		Row(String label, int need, int have)
		{
			this.label = label;
			this.need = need;
			this.have = have;
		}
	}
}

package com.questpath.planner;

import lombok.Builder;
import lombok.Value;
import net.runelite.api.Skill;

/**
 * One unit of the plan. Either "do quest X", "train skill Y to level Z via
 * method M", or "train skill Y to level Z (no method known)".
 */
@Value
@Builder
public class PlanStep
{
	PlanStepType type;

	/** Quest id (for QUEST) or training method id (for TRAINING). null for SKILL_GATE. */
	String referenceId;

	/** Display title shown in the UI / console. */
	String title;

	/** Sub-line — e.g. "Magic 55 → 65 via High Alch" or "Prereq for Lunar Diplomacy". */
	String subtitle;

	/** Skill being trained (for TRAINING / SKILL_GATE). null for QUEST. */
	Skill skill;

	int currentLevel;
	int targetLevel;

	/** Hours estimate. 0 if unknown. */
	double estimatedHours;

	/** GP cost. Negative = profit. 0 if unknown. */
	double estimatedGpCost;

	/** Free-form rationale ("Required for Shilo Village"). */
	String reasoning;
}

package com.questpath.planner;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;

/**
 * One quest in the dependency graph, after the graph builder has resolved its
 * prereqs and skill gates against a PlayerState.
 *
 * Mutable so the planner can flip status as it walks (e.g. a quest whose prereqs
 * become satisfied mid-walk after upstream quests get scheduled).
 */
@Data
@Builder
@AllArgsConstructor
public class QuestNode
{
	private final String questId;
	private final String displayName;

	/** Quest IDs this node depends on (only those also in the involved set). */
	@Builder.Default
	private final List<String> prerequisiteQuestIds = new ArrayList<>();

	/** Skill requirements, with current vs required filled in. */
	@Builder.Default
	private final List<SkillGate> skillGates = new ArrayList<>();

	private NodeStatus status;

	public List<SkillGate> unmetSkillGates()
	{
		List<SkillGate> unmet = new ArrayList<>();
		for (SkillGate g : skillGates)
		{
			if (!g.isMet())
			{
				unmet.add(g);
			}
		}
		return Collections.unmodifiableList(unmet);
	}
}

package com.questpath.planner;

import com.questpath.data.QuestDefinition;
import com.questpath.data.QuestRepository;
import com.questpath.data.TrainingMethod;
import com.questpath.game.PlayerState;
import com.questpath.game.QuestStatus;
import com.questpath.game.XpTable;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Skill;

/**
 * Orchestrator. Given a target quest and a PlayerState, returns an ordered
 * Plan: training steps inserted right before the quest that requires them,
 * then quests in topological order.
 *
 * Phase 3 design choices (deliberately simple):
 *   - One training method per skill gap (no chaining low-level → high-level methods)
 *   - Quest XP rewards do NOT close subsequent gaps yet (Phase 5)
 *   - No user weights yet (Phase 5)
 *   - SKILL_GATE step emitted when no method in DB qualifies — user fills in
 */
@Slf4j
@Singleton
public class PathPlanner
{
	private final QuestRepository repo;
	private final GapResolver gapResolver;

	@Inject
	public PathPlanner(QuestRepository repo, GapResolver gapResolver)
	{
		this.repo = repo;
		this.gapResolver = gapResolver;
	}

	public Plan plan(String targetQuestId, PlayerState state)
	{
		QuestDefinition target = repo.getQuest(targetQuestId);
		if (target == null)
		{
			log.warn("Unknown target quest id '{}'", targetQuestId);
			return Plan.empty(targetQuestId, targetQuestId);
		}

		DependencyGraph graph = DependencyGraph.build(repo, targetQuestId, state);

		// Filter to nodes still needing work, preserve insertion order.
		Map<String, QuestNode> pending = new LinkedHashMap<>();
		for (QuestNode node : graph.getNodes().values())
		{
			if (node.getStatus() != NodeStatus.DONE)
			{
				pending.put(node.getQuestId(), node);
			}
		}

		List<String> order = topoSort(pending);

		// Track skill levels and completed quests as we walk so we can re-evaluate
		// gates that earlier inserted training steps already covered.
		Map<Skill, Integer> skillLevelsSoFar = new EnumMap<>(Skill.class);
		state.getSkillLevels().forEach(skillLevelsSoFar::put);

		Set<String> completedSoFar = new HashSet<>();
		state.getQuestStates().forEach((id, status) -> {
			if (status == QuestStatus.DONE)
			{
				completedSoFar.add(id);
			}
		});

		List<PlanStep> steps = new ArrayList<>();
		for (String questId : order)
		{
			QuestNode node = pending.get(questId);
			for (SkillGate gate : node.getSkillGates())
			{
				int currentLevel = skillLevelsSoFar.getOrDefault(gate.getSkill(), 1);
				if (currentLevel >= gate.getRequiredLevel())
				{
					continue; // satisfied by earlier training or initial state
				}

				Optional<TrainingMethod> picked = gapResolver.pickMethodForSkill(
					gate.getSkill(), currentLevel, completedSoFar);

				if (picked.isPresent())
				{
					steps.add(buildTrainingStep(picked.get(), currentLevel, gate.getRequiredLevel(), node));
				}
				else
				{
					steps.add(buildSkillGateStep(gate.getSkill(), currentLevel, gate.getRequiredLevel(), node));
				}
				skillLevelsSoFar.put(gate.getSkill(), gate.getRequiredLevel());
			}
			steps.add(buildQuestStep(node));
			completedSoFar.add(questId);
		}

		return summarize(targetQuestId, target.getDisplayName(), steps);
	}

	private static List<String> topoSort(Map<String, QuestNode> nodes)
	{
		Map<String, Integer> inDegree = new HashMap<>();
		Map<String, List<String>> outgoing = new HashMap<>();
		for (String id : nodes.keySet())
		{
			inDegree.put(id, 0);
			outgoing.put(id, new ArrayList<>());
		}
		for (QuestNode n : nodes.values())
		{
			for (String prereq : n.getPrerequisiteQuestIds())
			{
				if (!nodes.containsKey(prereq))
				{
					continue; // prereq already DONE — skip edge
				}
				outgoing.get(prereq).add(n.getQuestId());
				inDegree.merge(n.getQuestId(), 1, Integer::sum);
			}
		}

		Deque<String> ready = new ArrayDeque<>();
		for (Map.Entry<String, Integer> e : inDegree.entrySet())
		{
			if (e.getValue() == 0)
			{
				ready.add(e.getKey());
			}
		}

		List<String> sorted = new ArrayList<>();
		while (!ready.isEmpty())
		{
			String id = ready.poll();
			sorted.add(id);
			for (String next : outgoing.get(id))
			{
				int d = inDegree.merge(next, -1, Integer::sum);
				if (d == 0)
				{
					ready.add(next);
				}
			}
		}

		if (sorted.size() != nodes.size())
		{
			log.warn("Topological sort incomplete: {} of {} nodes ordered (cycle?). Appending remainder unordered.",
				sorted.size(), nodes.size());
			for (String id : nodes.keySet())
			{
				if (!sorted.contains(id))
				{
					sorted.add(id);
				}
			}
		}
		return sorted;
	}

	private PlanStep buildQuestStep(QuestNode node)
	{
		String subtitle;
		if (node.getPrerequisiteQuestIds().isEmpty())
		{
			subtitle = "No quest prerequisites";
		}
		else
		{
			List<String> displayNames = new ArrayList<>();
			for (String prereqId : node.getPrerequisiteQuestIds())
			{
				QuestDefinition def = repo.getQuest(prereqId);
				displayNames.add(def != null ? def.getDisplayName() : prereqId);
			}
			subtitle = "Prereqs: " + String.join(", ", displayNames);
		}

		return PlanStep.builder()
			.type(PlanStepType.QUEST)
			.referenceId(node.getQuestId())
			.title("Quest: " + node.getDisplayName())
			.subtitle(subtitle)
			.reasoning("Required to reach the target quest.")
			.build();
	}

	private static PlanStep buildTrainingStep(
		TrainingMethod method, int currentLevel, int targetLevel, QuestNode forQuest)
	{
		int xpNeeded = XpTable.xpBetween(currentLevel, targetLevel);
		double hours = method.getXpPerHour() > 0 ? xpNeeded / method.getXpPerHour() : 0;
		double gpCost = -method.getGpPerHour() * hours; // gpPerHour > 0 means profit, so cost is negative
		String label = method.getSkill().getName() + " " + currentLevel + " → " + targetLevel;

		return PlanStep.builder()
			.type(PlanStepType.TRAINING)
			.referenceId(method.getId())
			.title("Train " + label)
			.subtitle("via " + humanize(method.getId())
				+ "  •  ~" + formatHours(hours) + "  •  " + formatGp(gpCost))
			.skill(method.getSkill())
			.currentLevel(currentLevel)
			.targetLevel(targetLevel)
			.estimatedHours(hours)
			.estimatedGpCost(gpCost)
			.reasoning("Needed for " + forQuest.getDisplayName())
			.build();
	}

	private static PlanStep buildSkillGateStep(Skill skill, int currentLevel, int targetLevel, QuestNode forQuest)
	{
		String label = skill.getName() + " " + currentLevel + " → " + targetLevel;
		return PlanStep.builder()
			.type(PlanStepType.SKILL_GATE)
			.title("Train " + label)
			.subtitle("No training method in database — fill in yourself")
			.skill(skill)
			.currentLevel(currentLevel)
			.targetLevel(targetLevel)
			.reasoning("Needed for " + forQuest.getDisplayName())
			.build();
	}

	private static Plan summarize(String targetId, String targetName, List<PlanStep> steps)
	{
		int questCount = 0;
		int trainingCount = 0;
		int gateCount = 0;
		double totalHours = 0;
		double totalGp = 0;
		for (PlanStep step : steps)
		{
			switch (step.getType())
			{
				case QUEST:
					questCount++;
					break;
				case TRAINING:
					trainingCount++;
					break;
				case SKILL_GATE:
					gateCount++;
					break;
			}
			totalHours += step.getEstimatedHours();
			totalGp += step.getEstimatedGpCost();
		}
		return new Plan(targetId, targetName, steps, questCount, trainingCount, gateCount, totalHours, totalGp);
	}

	private static String humanize(String snake)
	{
		StringBuilder sb = new StringBuilder();
		boolean upper = true;
		for (char c : snake.toCharArray())
		{
			if (c == '_')
			{
				sb.append(' ');
				upper = true;
			}
			else
			{
				sb.append(upper ? Character.toUpperCase(c) : c);
				upper = false;
			}
		}
		return sb.toString();
	}

	private static String formatHours(double hours)
	{
		if (hours <= 0)
		{
			return "?";
		}
		if (hours < 1)
		{
			return String.format("%.0f min", hours * 60);
		}
		return String.format("%.1f hr", hours);
	}

	private static String formatGp(double gp)
	{
		if (gp == 0)
		{
			return "free";
		}
		String sign = gp > 0 ? "-" : "+";
		double abs = Math.abs(gp);
		if (abs >= 1_000_000)
		{
			return sign + String.format("%.1fm gp", abs / 1_000_000);
		}
		if (abs >= 1_000)
		{
			return sign + String.format("%.0fk gp", abs / 1_000);
		}
		return sign + String.format("%.0f gp", abs);
	}
}

package com.questpath.planner;

/**
 * Status of a quest node in the dependency graph after evaluation against
 * a PlayerState. Drives color coding in the Phase 4 UI.
 */
public enum NodeStatus
{
	/** Quest is already done — short-circuit; no plan step needed. */
	DONE,
	/** All prereq quests done AND all skill gates met — can do right now. */
	READY,
	/** At least one prereq quest is incomplete. */
	BLOCKED_BY_QUEST,
	/** All prereq quests done but at least one skill gate unmet. */
	BLOCKED_BY_SKILL
}

package com.questpath.planner;

import java.util.Collections;
import java.util.List;
import lombok.Value;

/**
 * The full ordered plan from current state to target quest, plus rolled-up
 * estimates so the UI doesn't have to recompute.
 */
@Value
public class Plan
{
	String targetQuestId;
	String targetQuestDisplayName;

	List<PlanStep> steps;

	int questStepCount;
	int trainingStepCount;
	int skillGateStepCount;

	double totalEstimatedHours;
	double totalEstimatedGpCost;

	public List<PlanStep> getSteps()
	{
		return Collections.unmodifiableList(steps);
	}

	public boolean isAlreadyComplete()
	{
		return steps.isEmpty();
	}

	public static Plan empty(String targetId, String targetName)
	{
		return new Plan(targetId, targetName, Collections.emptyList(),
			0, 0, 0, 0.0, 0.0);
	}
}

package com.questpath.planner;

import com.questpath.QuestPathConfig;
import com.questpath.data.QuestRepository;
import com.questpath.data.TrainingMethod;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Optional;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Skill;

/**
 * Picks a single training method to fill a skill gap.
 *
 * Phase 5: weighted scoring. The user's Time / GP / AFK preference sliders
 * (held in QuestPathConfig) drive a scoring function over the qualifying
 * candidates; the highest-scoring method wins. When all weights are zero we
 * fall back to "highest xp/hr" as a sane default.
 */
@Slf4j
@Singleton
public class GapResolver
{
	private static final String QUEST_REQ_KEY = "QUEST";

	private final QuestRepository repo;
	private final QuestPathConfig config;

	@Inject
	public GapResolver(QuestRepository repo, QuestPathConfig config)
	{
		this.repo = repo;
		this.config = config;
	}

	/**
	 * Returns the best training method for {@code skill} given the current level
	 * and which quests are completed (or scheduled earlier in the plan).
	 *
	 * Empty if no method qualifies — caller emits a SKILL_GATE step.
	 */
	public Optional<TrainingMethod> pickMethodForSkill(
		Skill skill,
		int currentLevel,
		Set<String> completedQuestIds)
	{
		List<TrainingMethod> qualifying = new ArrayList<>();
		for (TrainingMethod m : repo.getTrainingMethodsForSkill(skill))
		{
			if (m.getMinLevel() > currentLevel)
			{
				continue;
			}
			if (!questPrereqsSatisfied(m, completedQuestIds))
			{
				continue;
			}
			qualifying.add(m);
		}
		if (qualifying.isEmpty())
		{
			return Optional.empty();
		}

		// Tolerate null config (used in tests that construct without DI).
		int timeW = config == null ? 5 : clamp(config.timeWeight());
		int gpW = config == null ? 5 : clamp(config.gpWeight());
		int afkW = config == null ? 5 : clamp(config.afkWeight());
		int totalW = timeW + gpW + afkW;

		// All zero → sensible default: pick fastest.
		if (totalW == 0)
		{
			return qualifying.stream().max(Comparator.comparingDouble(TrainingMethod::getXpPerHour));
		}

		// Normalize each sub-score to [0,1] across the candidate set so the user's
		// weights mix consistently regardless of the absolute numbers.
		double maxXp = qualifying.stream().mapToDouble(TrainingMethod::getXpPerHour).max().orElse(1.0);
		double maxGp = qualifying.stream().mapToDouble(TrainingMethod::getGpPerHour).max().orElse(0.0);
		double minGp = qualifying.stream().mapToDouble(TrainingMethod::getGpPerHour).min().orElse(0.0);
		double gpRange = maxGp - minGp;

		final int t = timeW, g = gpW, a = afkW, w = totalW;
		final double maxXpFinal = maxXp <= 0 ? 1.0 : maxXp;
		final double minGpFinal = minGp;
		final double gpRangeFinal = gpRange;

		return qualifying.stream()
			.max(Comparator.comparingDouble(m -> {
				double timeScore = m.getXpPerHour() / maxXpFinal;
				double gpScore = gpRangeFinal == 0 ? 0.5 : (m.getGpPerHour() - minGpFinal) / gpRangeFinal;
				double afkScore = m.getAfkRating() / 10.0;
				return (t * timeScore + g * gpScore + a * afkScore) / w;
			}));
	}

	private static int clamp(int v)
	{
		if (v < 0) return 0;
		if (v > 10) return 10;
		return v;
	}

	private static boolean questPrereqsSatisfied(TrainingMethod method, Set<String> completedQuestIds)
	{
		if (method.getRequirements() == null || method.getRequirements().isEmpty())
		{
			return true;
		}
		String questReq = method.getRequirements().get(QUEST_REQ_KEY);
		if (questReq == null)
		{
			return true;
		}
		return completedQuestIds.contains(questReq);
	}
}

package com.questpath.planner;

import com.questpath.data.QuestDefinition;
import com.questpath.data.QuestRepository;
import com.questpath.game.PlayerState;
import com.questpath.game.QuestStatus;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Skill;

/**
 * Builds the prereq DAG for a target quest and stamps each node with its
 * status against the supplied PlayerState.
 *
 * Defends against cycles (shouldn't exist in OSRS quests but log + skip if found).
 * Defends against missing quest definitions (log warning, treat as a leaf).
 */
@Slf4j
public final class DependencyGraph
{
	private final Map<String, QuestNode> nodesById;

	private DependencyGraph(Map<String, QuestNode> nodesById)
	{
		this.nodesById = nodesById;
	}

	public Map<String, QuestNode> getNodes()
	{
		return nodesById;
	}

	public QuestNode getNode(String questId)
	{
		return nodesById.get(questId);
	}

	public int size()
	{
		return nodesById.size();
	}

	/** Walks prereqs from {@code targetQuestId}, evaluating each node against {@code state}. */
	public static DependencyGraph build(QuestRepository repo, String targetQuestId, PlayerState state)
	{
		Map<String, QuestNode> nodes = new LinkedHashMap<>();
		Set<String> visiting = new HashSet<>();
		walk(targetQuestId, repo, state, nodes, visiting);
		return new DependencyGraph(nodes);
	}

	private static void walk(
		String questId,
		QuestRepository repo,
		PlayerState state,
		Map<String, QuestNode> nodes,
		Set<String> visiting)
	{
		if (nodes.containsKey(questId))
		{
			return;
		}
		if (!visiting.add(questId))
		{
			log.warn("Cycle detected at quest id '{}' — skipping re-entry", questId);
			return;
		}

		QuestDefinition def = repo.getQuest(questId);
		if (def == null)
		{
			log.warn("Quest '{}' referenced but not in repository — adding leaf placeholder", questId);
			nodes.put(questId, QuestNode.builder()
				.questId(questId)
				.displayName(questId)
				.status(NodeStatus.BLOCKED_BY_QUEST)
				.build());
			visiting.remove(questId);
			return;
		}

		// Recurse into prereqs first so they're inserted before the dependent quest.
		List<String> prereqIds = def.getPrerequisiteQuestIds() == null
			? new ArrayList<>()
			: new ArrayList<>(def.getPrerequisiteQuestIds());
		for (String prereqId : prereqIds)
		{
			walk(prereqId, repo, state, nodes, visiting);
		}

		List<SkillGate> gates = new ArrayList<>();
		if (def.getSkillRequirements() != null)
		{
			for (Map.Entry<Skill, Integer> req : def.getSkillRequirements().entrySet())
			{
				gates.add(new SkillGate(
					req.getKey(),
					req.getValue(),
					state.getSkillLevel(req.getKey())));
			}
		}

		NodeStatus status = computeStatus(questId, prereqIds, gates, state, nodes);

		nodes.put(questId, QuestNode.builder()
			.questId(questId)
			.displayName(def.getDisplayName())
			.prerequisiteQuestIds(prereqIds)
			.skillGates(gates)
			.status(status)
			.build());

		visiting.remove(questId);
	}

	private static NodeStatus computeStatus(
		String questId,
		List<String> prereqIds,
		List<SkillGate> gates,
		PlayerState state,
		Map<String, QuestNode> existingNodes)
	{
		if (state.getQuestStatus(questId) == QuestStatus.DONE)
		{
			return NodeStatus.DONE;
		}

		boolean prereqsBlocked = false;
		for (String prereqId : prereqIds)
		{
			QuestStatus s = state.getQuestStatus(prereqId);
			if (s != QuestStatus.DONE)
			{
				prereqsBlocked = true;
				break;
			}
		}

		boolean skillsBlocked = false;
		for (SkillGate gate : gates)
		{
			if (!gate.isMet())
			{
				skillsBlocked = true;
				break;
			}
		}

		if (prereqsBlocked)
		{
			return NodeStatus.BLOCKED_BY_QUEST;
		}
		if (skillsBlocked)
		{
			return NodeStatus.BLOCKED_BY_SKILL;
		}
		return NodeStatus.READY;
	}
}

package com.questpath.planner;

public enum PlanStepType
{
	/** Do this quest. */
	QUEST,
	/** Train this skill via this method (we found a fitting method). */
	TRAINING,
	/** Train this skill, but the database has no method we could pick — user fills in. */
	SKILL_GATE
}

package com.questpath.planner;

import lombok.Value;
import net.runelite.api.Skill;

/**
 * One skill requirement on a quest node, evaluated against the current player state.
 *
 * If currentLevel >= requiredLevel, {@link #isMet()} is true and the planner skips it.
 * Otherwise the planner inserts a TRAINING (or SKILL_GATE) step before the gating quest.
 */
@Value
public class SkillGate
{
	Skill skill;
	int requiredLevel;
	int currentLevel;

	public boolean isMet()
	{
		return currentLevel >= requiredLevel;
	}

	public int levelsToTrain()
	{
		return Math.max(0, requiredLevel - currentLevel);
	}
}

