/**
 * Top-level shape of overrides.json. Gson deserializes the file into this object.
 *
 * <pre>
 * {
 *   "quests": { "lunar_diplomacy": { ... }, ... },
 *   "trainingMethods": [ { "id": "willows_at_draynor", ... }, ... ]
 * }
 * </pre>
 */
