package com.questpath.data;

import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;
import net.runelite.api.Skill;

/**
 * One quest's definition — name, prereqs, skill walls, rewards.
 *
 * Source priority at load time: hand-authored overrides.json wins, wiki fills gaps.
 * Field defaults stay non-null so the planner can iterate without null checks.
 */
@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class QuestDefinition
{
	/** Stable snake_case id (e.g. "lunar_diplomacy"). Used in prereq edges and serialization keys. */
	private String id;

	/** Display name as shown in-game (e.g. "Lunar Diplomacy"). */
	private String displayName;

	/** Quest points awarded on completion. */
	private int questPointReward;

	/** Quest IDs that must be completed before this quest can start. */
	@Builder.Default
	private List<String> prerequisiteQuestIds = new java.util.ArrayList<>();

	/** Skill level required to start the quest. Boostable distinctions live elsewhere (future). */
	@Builder.Default
	private Map<Skill, Integer> skillRequirements = new EnumMap<>(Skill.class);

	/** XP rewards granted on completion, per skill. */
	@Builder.Default
	private Map<Skill, Integer> skillRewards = new EnumMap<>(Skill.class);

	/** Recommended (not strict) combat level. 0 if irrelevant. */
	private int recommendedCombatLevel;

	/** Canonical wiki URL for the quest. */
	private String wikiUrl;

	/** Members-only? */
	private boolean members;

	/** Wiki estimate of completion time in minutes. */
	private int estimatedMinutes;

	/** Free-form notes; useful for "boostable", "AFK", caveats etc. */
	private String notes;

	/**
	 * Quest Helper category: "F2P" / "P2P" / "MINIQUEST" / "ACHIEVEMENT_DIARY".
	 * Null for hand-authored entries that don't specify it.
	 */
	private String questType;

	/**
	 * Quest Helper difficulty: NOVICE / INTERMEDIATE / EXPERIENCED / MASTER /
	 * GRANDMASTER / SPECIAL / MINIQUEST / ACHIEVEMENT_DIARY. Null when unknown.
	 */
	private String difficulty;

	/** Quest points required to start the quest (if any). 0 = no QP gate. */
	private int questPointRequirement;
}

package com.questpath.data;

import java.util.HashMap;
import java.util.Map;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;
import net.runelite.api.Skill;

/**
 * One way to train a skill — chopping willows, fletching darts, splashing, etc.
 *
 * The planner uses this to fill skill gaps that quest XP rewards alone don't close.
 * Numbers are approximate level-bucketed estimates; refinement is a Phase 6 problem.
 */
@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class TrainingMethod
{
	/** Stable snake_case id (e.g. "willows_at_draynor"). */
	private String id;

	/** Skill this method trains. */
	private Skill skill;

	/** Minimum level to start (skill requirement). */
	private int minLevel;

	/** Level above which a faster method generally wins. Useful for ordering candidates. */
	private int maxEffectiveLevel;

	/** Approximate XP per hour at the level range. */
	private double xpPerHour;

	/** GP per hour: positive = profit, negative = cost. */
	private double gpPerHour;

	/** 0 (full attention) - 10 (set & forget). */
	private int afkRating;

	/** 0 (safe) - 10 (deep wilderness, PVP zone). */
	private int riskLevel;

	/**
	 * Other prereqs beyond minLevel. Loose schema:
	 *   {"QUEST": "shilo_village"}, {"SKILL_FISHING": "30"}, {"MEMBERS": "true"}
	 * The planner inspects the keys it cares about and ignores the rest.
	 */
	@Builder.Default
	private Map<String, String> requirements = new HashMap<>();

	/** Human-readable location for the UI. */
	private String location;

	/** Free-form tips (banking notes, click cycles, etc.). */
	private String notes;
}

package com.questpath.data;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Loads the bundled overrides.json from the plugin classpath. This is the
 * authoritative data source — wins over wiki-fetched data when both exist.
 *
 * Phase 2: read once at startup. A future iteration may hot-reload from disk
 * for power users, but the bundled file is enough to get the planner running.
 */
@Slf4j
@Singleton
public class OverrideLoader
{
	private static final String RESOURCE_PATH = "/data/overrides.json";

	private final OverrideData cached;

	/**
	 * Plugin Hub forbids constructing fresh Gson instances in plugin code —
	 * we inject the client's shared one at runtime. Tests construct one
	 * explicitly via {@link #OverrideLoader(Gson)} since they don't run inside
	 * Guice.
	 */
	@Inject
	public OverrideLoader(Gson gson)
	{
		this.cached = loadFromClasspath(gson);
	}

	public OverrideData getData()
	{
		return cached;
	}

	private OverrideData loadFromClasspath(Gson gson)
	{
		try (InputStream in = getClass().getResourceAsStream(RESOURCE_PATH))
		{
			if (in == null)
			{
				log.warn("overrides.json not found on classpath at {}", RESOURCE_PATH);
				return emptyData();
			}

			try (Reader reader = new InputStreamReader(in, StandardCharsets.UTF_8))
			{
				OverrideData data = gson.fromJson(reader, OverrideData.class);
				if (data == null)
				{
					log.warn("overrides.json parsed to null — returning empty");
					return emptyData();
				}
				int questCount = data.getQuests() == null ? 0 : data.getQuests().size();
				int methodCount = data.getTrainingMethods() == null ? 0 : data.getTrainingMethods().size();
				log.info("Loaded overrides.json: {} quests, {} training methods", questCount, methodCount);
				return data;
			}
		}
		catch (IOException e)
		{
			log.error("Failed to read overrides.json", e);
			return emptyData();
		}
	}

	private static OverrideData emptyData()
	{
		return new OverrideData(new java.util.HashMap<>(), Collections.emptyList());
	}
}

package com.questpath.data;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Skill;

/**
 * Single source of truth for quest + training method lookups.
 *
 * Merge rule: hand-authored override entries beat wiki-fetched entries on the same id.
 * Wiki data fills gaps. The planner asks this class only — it doesn't know about either source.
 */
@Slf4j
@Singleton
public class QuestRepository
{
	private final Map<String, QuestDefinition> quests;
	private final List<TrainingMethod> trainingMethods;

	@Inject
	public QuestRepository(OverrideLoader overrideLoader, WikiDataFetcher wikiDataFetcher)
	{
		final OverrideData overrides = overrideLoader.getData();
		final Map<String, QuestDefinition> wikiQuests = wikiDataFetcher.fetchQuests();

		this.quests = sanitize(mergeQuests(overrides.getQuests(), wikiQuests));
		this.trainingMethods = overrides.getTrainingMethods() == null
			? Collections.emptyList()
			: new ArrayList<>(overrides.getTrainingMethods());

		log.info("QuestRepository ready: {} quests, {} training methods",
			this.quests.size(), this.trainingMethods.size());
	}

	/**
	 * Defensive cleanup before the data is exposed to the planner / tree view:
	 *   1. Drop self-referential prereqs ({@code X} → {@code X}). Quest Helper's
	 *      helper classes sometimes reference their own enum entry for state-tracking,
	 *      and our regex parser can't tell that from a real prereq edge — see
	 *      {@code gertrudes_cat} in the bundled data. A self-prereq would otherwise
	 *      explode the dependency tree into infinite recursion.
	 *   2. Drop dangling prereq references whose target id isn't in the bundle.
	 *      The planner already tolerates these but the tree view shouldn't waste
	 *      a row asking the user about a quest we know nothing about.
	 */
	private static Map<String, QuestDefinition> sanitize(Map<String, QuestDefinition> raw)
	{
		int selfPrereqsRemoved = 0;
		int danglingPrereqsRemoved = 0;
		for (QuestDefinition q : raw.values())
		{
			List<String> prereqs = q.getPrerequisiteQuestIds();
			if (prereqs == null || prereqs.isEmpty())
			{
				continue;
			}
			List<String> cleaned = new ArrayList<>(prereqs.size());
			for (String prereqId : prereqs)
			{
				if (prereqId == null || prereqId.equals(q.getId()))
				{
					selfPrereqsRemoved++;
					continue;
				}
				if (!raw.containsKey(prereqId))
				{
					danglingPrereqsRemoved++;
					continue;
				}
				cleaned.add(prereqId);
			}
			if (cleaned.size() != prereqs.size())
			{
				q.setPrerequisiteQuestIds(cleaned);
			}
		}
		if (selfPrereqsRemoved > 0 || danglingPrereqsRemoved > 0)
		{
			log.info("QuestRepository sanitized: dropped {} self-prereqs, {} dangling prereqs",
				selfPrereqsRemoved, danglingPrereqsRemoved);
		}
		return raw;
	}

	private static Map<String, QuestDefinition> mergeQuests(
		Map<String, QuestDefinition> overrides,
		Map<String, QuestDefinition> wiki)
	{
		final Map<String, QuestDefinition> merged = new HashMap<>();
		// Wiki first so overrides can replace.
		if (wiki != null)
		{
			merged.putAll(wiki);
		}
		if (overrides != null)
		{
			merged.putAll(overrides);
		}
		return merged;
	}

	/** Look up a quest by id. Returns null if unknown — caller decides what to do. */
	public QuestDefinition getQuest(String questId)
	{
		return quests.get(questId);
	}

	/** All known quests, in insertion order (i.e. unspecified). Read-only. */
	public Collection<QuestDefinition> getAllQuests()
	{
		return Collections.unmodifiableCollection(quests.values());
	}

	/** Training methods that target a given skill, in insertion order. */
	public List<TrainingMethod> getTrainingMethodsForSkill(Skill skill)
	{
		return trainingMethods.stream()
			.filter(m -> m.getSkill() == skill)
			.collect(Collectors.toList());
	}

	/** All known training methods. Read-only. */
	public List<TrainingMethod> getAllTrainingMethods()
	{
		return Collections.unmodifiableList(trainingMethods);
	}

	public int questCount()
	{
		return quests.size();
	}

	public int trainingMethodCount()
	{
		return trainingMethods.size();
	}
}

package com.questpath.data;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Loads bundled wiki snapshot data ({@code /data/wiki_data.json}). The snapshot
 * was scraped via the OSRS Wiki MediaWiki API at build time and contains every
 * quest's basic metadata (name, members, QP reward). A subset of quests also
 * have prereqs / skill requirements / skill rewards filled in from the wiki;
 * the rest carry empty collections (the planner sees them as quests with no
 * gates).
 *
 * Hand-authored {@link OverrideLoader} data wins over wiki data on id collision —
 * {@link QuestRepository} handles that merge.
 */
@Slf4j
@Singleton
public class WikiDataFetcher
{
	private static final String RESOURCE_PATH = "/data/wiki_data.json";

	private final Map<String, QuestDefinition> cached;

	/** Plugin Hub forbids constructing fresh Gson instances; we inject the
	 *  client's shared one. Tests must pass {@code new Gson()} explicitly. */
	@Inject
	public WikiDataFetcher(Gson gson)
	{
		this.cached = loadFromClasspath(gson);
	}

	/** Returns wiki-derived quest definitions, keyed by id. Never null. */
	public Map<String, QuestDefinition> fetchQuests()
	{
		return cached;
	}

	private static Map<String, QuestDefinition> loadFromClasspath(Gson gson)
	{
		try (InputStream in = WikiDataFetcher.class.getResourceAsStream(RESOURCE_PATH))
		{
			if (in == null)
			{
				log.warn("wiki_data.json not on classpath at {} — wiki snapshot unavailable", RESOURCE_PATH);
				return Collections.emptyMap();
			}
			try (Reader reader = new InputStreamReader(in, StandardCharsets.UTF_8))
			{
				OverrideData data = gson.fromJson(reader, OverrideData.class);
				if (data == null || data.getQuests() == null)
				{
					return Collections.emptyMap();
				}
				log.info("Wiki snapshot loaded: {} quests", data.getQuests().size());
				return new HashMap<>(data.getQuests());
			}
		}
		catch (IOException e)
		{
			log.error("Failed to read wiki_data.json", e);
			return Collections.emptyMap();
		}
	}
}

package com.questpath.game;

/**
 * Mirror of RuneLite's QuestState but kept independent so the planner doesn't
 * couple to the live client API. Mapping happens in GameStateReader.
 */
public enum QuestStatus
{
	NOT_STARTED,
	IN_PROGRESS,
	DONE
}

package com.questpath.game;

import java.util.EnumMap;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;

/**
 * Reads the live RuneLite client into a PlayerState snapshot. When not logged
 * in (LOGIN_SCREEN, HOPPING, etc.) returns PlayerState.empty() so the planner
 * can still produce a fresh-account plan.
 *
 * Phase 3 is mostly stub-driven (Rodney can't log in dev RuneLite with Jagex
 * auth) but the wiring is real — once we have a logged-in test account, this
 * reads accurately without further changes.
 */
@Slf4j
@Singleton
public class GameStateReader
{
	private final Client client;

	@Inject
	public GameStateReader(Client client)
	{
		this.client = client;
	}

	/** Snapshots the current player state, or empty() when not logged in. */
	public PlayerState snapshot()
	{
		if (client == null || client.getGameState() != GameState.LOGGED_IN)
		{
			log.debug("GameStateReader: not logged in, returning empty PlayerState");
			return PlayerState.empty();
		}

		Map<String, QuestStatus> questStates = new HashMap<>();
		for (Quest quest : Quest.values())
		{
			questStates.put(idForQuest(quest), translate(quest.getState(client)));
		}

		Map<Skill, Integer> skillLevels = new EnumMap<>(Skill.class);
		for (Skill skill : Skill.values())
		{
			if (skill == Skill.OVERALL)
			{
				continue;
			}
			skillLevels.put(skill, client.getRealSkillLevel(skill));
		}

		// QP read deferred — VarPlayer constant differs across RuneLite versions.
		// Phase 3 doesn't gate on QP yet; Phase 5+ will.
		PlayerState.PlayerStateBuilder builder = PlayerState.builder().questPoints(0);

		// PlayerState's @Singular doesn't accept Maps directly; fold them in.
		questStates.forEach(builder::questState);
		skillLevels.forEach(builder::skillLevel);

		return builder.build();
	}

	/** Converts RuneLite's Quest enum name into the snake_case ids the planner uses. */
	static String idForQuest(Quest quest)
	{
		return quest.name().toLowerCase();
	}

	private static QuestStatus translate(QuestState state)
	{
		if (state == null)
		{
			return QuestStatus.NOT_STARTED;
		}
		switch (state)
		{
			case FINISHED:
				return QuestStatus.DONE;
			case IN_PROGRESS:
				return QuestStatus.IN_PROGRESS;
			case NOT_STARTED:
			default:
				return QuestStatus.NOT_STARTED;
		}
	}
}

package com.questpath.game;

import java.util.Map;
import lombok.Builder;
import lombok.Singular;
import lombok.Value;
import net.runelite.api.Skill;

/**
 * Immutable snapshot of "where the player is" — completed quests + skill levels
 * + QP. The planner reads this and the live game; tests construct it directly.
 *
 * Use the builder for ergonomic construction; missing fields default to a
 * fresh-account state (level 1 everything, nothing done). @Singular gives us
 * questState(id, status) / skillLevel(skill, level) builder methods.
 */
@Value
@Builder(toBuilder = true)
public class PlayerState
{
	@Singular
	Map<String, QuestStatus> questStates;

	@Singular
	Map<Skill, Integer> skillLevels;

	int questPoints;

	/** Fresh-account snapshot: level 1 everything, no quests done, 0 QP. */
	public static PlayerState empty()
	{
		return PlayerState.builder().build();
	}

	/** Defaults to NOT_STARTED for any quest not in the map. */
	public QuestStatus getQuestStatus(String questId)
	{
		QuestStatus s = questStates.get(questId);
		return s == null ? QuestStatus.NOT_STARTED : s;
	}

	/** Defaults to 1 for any skill not in the map. */
	public int getSkillLevel(Skill skill)
	{
		Integer level = skillLevels.get(skill);
		return level == null ? 1 : level;
	}
}

package com.questpath.game;

/**
 * Standard OSRS XP-for-level lookup. The formula is well-defined:
 *
 *   xp(L) = floor( 0.25 * sum from x=1 to L-1 of floor( x + 300 * 2^(x/7) ) )
 *
 * which gives xp(2) = 83, xp(99) = 13_034_431, xp(126) = 200_000_000 (virtual).
 *
 * Table cached at class-load time. Levels above 99 cap at 99.
 */
public final class XpTable
{
	private static final int MAX_LEVEL = 99;
	private static final int[] XP_FOR_LEVEL = computeTable();

	private XpTable() {}

	private static int[] computeTable()
	{
		int[] table = new int[MAX_LEVEL + 1];
		double sum = 0;
		table[1] = 0;
		for (int level = 1; level < MAX_LEVEL; level++)
		{
			sum += Math.floor(level + 300.0 * Math.pow(2, level / 7.0));
			table[level + 1] = (int) Math.floor(sum / 4.0);
		}
		return table;
	}

	/** XP required to reach the start of {@code level}. xpForLevel(1) = 0, xpForLevel(99) = 13034431. */
	public static int xpForLevel(int level)
	{
		if (level < 1)
		{
			return 0;
		}
		if (level > MAX_LEVEL)
		{
			return XP_FOR_LEVEL[MAX_LEVEL];
		}
		return XP_FOR_LEVEL[level];
	}

	/** XP needed to go from {@code fromLevel} (current) to {@code toLevel} (target). Never negative. */
	public static int xpBetween(int fromLevel, int toLevel)
	{
		return Math.max(0, xpForLevel(toLevel) - xpForLevel(fromLevel));
	}
}
